package models

import "time"

type DatabaseIndexColumn struct {
	Name      string `json:"name"`
	Direction string `json:"direction"`
	Nulls     string `json:"nulls"`
}

type DatabaseIndexDefinition struct {
	TableName      string                `json:"table_name"`
	Columns        []DatabaseIndexColumn `json:"columns"`
	IncludeColumns []string              `json:"include_columns"`
}

// ManagedDatabaseIndex is the ownership registry. Catalog names are generated by
// the server, never supplied by an API caller. Existing indexes are never adopted.
type ManagedDatabaseIndex struct {
	ID                  int64                    `json:"id" gorm:"primaryKey"`
	Label               string                   `json:"label" gorm:"size:80;not null"`
	Purpose             string                   `json:"purpose" gorm:"size:256;not null"`
	Recipe              string                   `json:"recipe" gorm:"size:40;not null"`
	ParameterPath       string                   `json:"parameter_path" gorm:"size:256;not null"`
	Definition          *DatabaseIndexDefinition `json:"definition,omitempty" gorm:"type:jsonb;serializer:json"`
	Status              string                   `json:"status" gorm:"size:24;not null"`
	Message             string                   `json:"message" gorm:"size:512"`
	ActiveName          string                   `json:"active_name" gorm:"size:63"`
	ActiveOID           int64                    `json:"-" gorm:"column:active_oid"`
	ActiveDefinition    string                   `json:"-"`
	ActiveToken         string                   `json:"-" gorm:"size:64"`
	CandidateName       string                   `json:"-" gorm:"size:63"`
	CandidateOID        int64                    `json:"-" gorm:"column:candidate_oid"`
	CandidateToken      string                   `json:"-" gorm:"size:64"`
	CandidateDefinition string                   `json:"-"`
	CancelRequested     bool                     `json:"cancel_requested"`
	CreatedBy           int64                    `json:"created_by"`
	CreatedAt           time.Time                `json:"created_at"`
	UpdatedAt           time.Time                `json:"updated_at"`
}

func (ManagedDatabaseIndex) TableName() string { return "managed_database_indexes" }

// DatabaseIndexStorageProbe is refreshed on the PostgreSQL host, not the API
// host. It covers both PGDATA and WAL filesystems; stale readings fail closed.
type DatabaseIndexStorageProbe struct {
	ID         int       `gorm:"primaryKey;autoIncrement:false;check:db_index_probe_singleton,id = 1"`
	TotalBytes int64     `json:"total_bytes" gorm:"not null"`
	FreeBytes  int64     `json:"free_bytes" gorm:"not null"`
	MeasuredAt time.Time `json:"measured_at" gorm:"not null"`
}

func (DatabaseIndexStorageProbe) TableName() string { return "database_index_storage_probes" }
